from z3 import *

s = Solver()
x = [Int(f'x_{i}') for i in range(1, 21)]

for i in range(20):
    s.add(Or(x[i] == 0, x[i] == 1, x[i] == 2))

for j in range(3):
    s.add(Sum([If(x[i] == j, i + 1, 0) for i in range(20)]) == 70)

if s.check() == sat:
    m = s.model()
    print([m[x[i]].as_long() for i in range(20)])
else:
    print("UNSAT")
